import { createWorkspace, teardownWorkspace } from '@tigrisdata/agent-kit';
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import * as fs from 'fs/promises';
import * as path from 'path';

const STATE_FILE = path.join('/home/user/pool', 'pool-state.json');

export async function provisionPool(n: number) {
  const promises = [];
  for (let i = 1; i <= n; i++) {
    const name = `pool-${n}-${i}`;
    promises.push(createWorkspace(name, {
      ttl: { days: 1 },
      credentials: { role: 'Editor' }
    }));
  }

  const results = await Promise.all(promises);

  const workspaces = results.map(res => ({
    name: res.name,
    bucket: res.bucket,
    credentials: {
      accessKeyId: res.credentials.accessKeyId,
      secretAccessKey: res.credentials.secretAccessKey
    }
  }));

  await fs.writeFile(STATE_FILE, JSON.stringify({ workspaces }, null, 2));
}

export async function assignTask(agentIndex: number, text: string) {
  const stateData = await fs.readFile(STATE_FILE, 'utf-8');
  const state = JSON.parse(stateData);

  if (agentIndex < 1 || agentIndex > state.workspaces.length) {
    throw new Error(`Agent index ${agentIndex} out of range`);
  }

  const workspace = state.workspaces[agentIndex - 1];

  const s3 = new S3Client({
    region: 'REDACTED',
    endpoint: 'REDACTED',
    credentials: {
      accessKeyId: workspace.credentials.accessKeyId,
      secretAccessKey: workspace.credentials.secretAccessKey
    }
  });

  await s3.send(new PutObjectCommand({
    Bucket: workspace.bucket,
    Key: 'task.txt',
    Body: text
  }));
}

export async function status() {
  const stateData = await fs.readFile(STATE_FILE, 'utf-8');
  const state = JSON.parse(stateData);

  console.log(`pool size: ${state.workspaces.length}`);
  for (const ws of state.workspaces) {
    console.log(ws.bucket);
  }
}

export async function teardownPool() {
  const stateData = await fs.readFile(STATE_FILE, 'utf-8');
  const state = JSON.parse(stateData);

  const promises = state.workspaces.map((ws: any) => teardownWorkspace(ws.name));
  const results = await Promise.allSettled(promises);

  await fs.unlink(STATE_FILE);

  const failures = results.filter(r => r.status === 'rejected');
  if (failures.length > 0) {
    throw new Error(`Failed to teardown ${failures.length} workspaces`);
  }
}

import { provisionPool, assignTask, status, teardownPool } from './manager';

async function main() {
  const args = process.argv.slice(2);
  const command = args[0];

  try {
    if (command === 'provision') {
      const n = parseInt(args[1], 10);
      if (isNaN(n) || n <= 0) throw new Error('Invalid N');
      await provisionPool(n);
    } else if (command === 'assign-task') {
      const index = parseInt(args[1], 10);
      const text = args[2];
      if (isNaN(index) || typeof text !== 'string') throw new Error('Invalid arguments for assign-task');
      await assignTask(index, text);
    } else if (command === 'status') {
      await status();
    } else if (command === 'teardown') {
      await teardownPool();
    } else {
      console.error('Usage: cli.ts <provision N | assign-task index text | status | teardown>');
      process.exitCode = 1;
    }
  } catch (err) {
    console.error(err);
    process.exitCode = 1;
  }
}

main();

